mapper.select:
SELECT r.role_id, r.tenant_id, r.role_code, r.role_nm, r.role_dc, r.use_at, r.is_system_role, COALESCE(rc.user_count, 0) AS user_count, r.created_at, r.updated_at FROM tb_role r LEFT JOIN ( SELECT role_id, COUNT(*) AS user_count FROM tb_login_account_role GROUP BY role_id ) rc ON rc.role_id = r.role_id WHERE r.tenant_id = #{tenantId}
AND r.use_at = #{useAt}
ORDER BY r.role_id ASC

SELECT role_id
FROM tb_role
WHERE tenant_id = #{tenantId}
  AND role_code = #{roleCode}

SELECT u.login_id
FROM tb_user u
WHERE u.user_id = #{userId}
  AND u.tenant_id = #{tenantId}
LIMIT 1

mapper.delete:
DELETE FROM tb_login_account_role
WHERE role_id = #{roleId}
  AND login_id = CAST(#{loginId} AS BIGINT)
  AND login_id IN (
      SELECT la.login_id
      FROM tb_login_account la
      WHERE la.tenant_id = #{tenantId}
  )
